sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    restrictTrades();

    function restrictTrades() {

        var trdquery = "",
            user = new GlideRecord('sys_user');

        if (user.get(gs.getUserID()) && user.u_associated_business_markets) {

            var markets = user.u_associated_business_markets.toString().split(',');

            trdquery = "custodytrade_owning_businessIN" + markets;
            // MSSCUSTODY-5858 - Check if user has access to "GC HK" or "GC UK"
            if (markets.indexOf("GC HK") !== -1)
                trdquery += "^ORcustodytrade_other_businessINGC HK";

            if (markets.indexOf("GC UK") !== -1)
                trdquery += "^ORcustodytrade_other_businessINGC UK";

        } else {
            //no record should be visible if user has no associated owning business
            trdquery = "custodytrade_owning_business=NothingVisible";
        }

        current.addEncodedQuery(trdquery);

    }

})(current, previous);
